// Examp
const now = new Date();

const options = {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: true,
  timeZone: 'Africa/Lagos'
};

const formattedDate = new Intl.DateTimeFormat(
  'en-GB',
  options
).format(now);

return [
  {
    json: {
      dayOfWeek: new Intl.DateTimeFormat('en-GB', {
        weekday: 'long',
        timeZone: 'Africa/Lagos'
      }).format(now),

      day: new Intl.DateTimeFormat('en-GB', {
        day: 'numeric',
        timeZone: 'Africa/Lagos'
      }).format(now),

      month: new Intl.DateTimeFormat('en-GB', {
        month: 'long',
        timeZone: 'Africa/Lagos'
      }).format(now),

      year: new Intl.DateTimeFormat('en-GB', {
        year: 'numeric',
        timeZone: 'Africa/Lagos'
      }).format(now),

      time: new Intl.DateTimeFormat('en-GB', {
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hour12: true,
        timeZone: 'Africa/Lagos'
      }).format(now),

      fullDateAndTime: formattedDate
    }
  }
];
